css:
@keyframes rise{
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.bubble.s-WovOnquG99wn{
    background: var(--accent-soft);
    border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
    color: var(--ink);
    border-radius: 14px 14px 4px 14px;
    padding: 9px 13px;
    max-width: min(80%, 560px);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    font-size: 14.5px;
    transition: opacity var(--panel) var(--ease);
  }

.stamp.s-WovOnquG99wn{
    font-size: 10.5px;
    color: var(--ink-faint);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    pointer-events: none;
    user-select: none;
  }

.card.s-dnXP_MrVFkb5{
    width: 100%;
    background: var(--bg-raised);
    border: 1px solid var(--line);
    border-radius: 12px;
    box-shadow: 0 2px 10px rgb(0 0 0 / 0.16);
    display: flex;
    flex-direction: column;
    overflow: hidden;

    transition: border-color var(--panel) var(--ease), box-shadow var(--panel) var(--ease);
  }

.card.focused.s-dnXP_MrVFkb5{
    border-color: color-mix(in srgb, var(--accent) 62%, var(--line));
    box-shadow: 0 6px 22px rgb(0 0 0 / 0.28);
  }

.quote.s-dnXP_MrVFkb5{
    flex: 1; min-width: 0; margin: 0;
    font-size: 11.5px; line-height: 1.35; color: var(--ink-faint);
    border-left: 2px solid var(--accent);
    padding-left: 7px;
    display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
    overflow: hidden;
  }

.x.s-dnXP_MrVFkb5{
    color: var(--ink-faint);
    font-size: 15px; line-height: 1;
    flex: none;
    width: 24px; height: 24px;
    display: grid; place-items: center;
    border-radius: 6px;
  }

.body.s-dnXP_MrVFkb5{
    padding: 0 11px;
    max-height: min(46vh, 380px);
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
  }

textarea.s-dnXP_MrVFkb5{
    flex: 1; min-width: 0;
    resize: none;
    background: transparent;
    border: 0;
    padding: 4px 0;
    color: var(--ink);
    font-family: var(--sans);

    font-size: 16px;
    line-height: 1.35;
    max-height: 132px;
    outline: none;
  }

.send.s-dnXP_MrVFkb5{
    width: 24px; height: 24px; flex: none;
    border-radius: 50%;
    background: var(--accent);
    color: #14100d;
    font-size: 13px; font-weight: 600;
    display: grid; place-items: center;
  }
